  home_title: "Rägiräupli Playgroup",
  home_hero_title: "Welcome to the Rägiräupli",
  home_hero_text: "A loving place to grow, play and discover – for children from 2.5 years old until they start kindergarten.",
  home_overview_title: "At a Glance",
  home_card_konzept_title: "Concept",
  home_card_konzept_text: "Our pedagogy, principles and daily playgroup life.",
  home_card_team_title: "Team",
  home_card_team_text: "Who takes care of your child.",
  home_card_tarife_title: "Hours & Fees",
  home_card_tarife_text: "Opening hours and prices at a glance.",
  home_card_anmeldung_title: "Registration",
